import json
from pathlib import Path

import numpy as np
import torch
from PIL import Image
from torch.utils.data import Dataset, DataLoader


class BlenderNeRFDataset(Dataset):

    def __init__(
        self,
        root_dir,
        split="train",
        img_wh=(400, 400),
        white_background=True,
    ):
        super().__init__()

        self.root_dir = Path(root_dir)
        self.split = split
        self.img_wh = img_wh
        self.white_background = white_background

        self.W, self.H = img_wh

        # Load transforms JSON
        transforms_path = (
            self.root_dir / f"transforms_{split}.json"
        )

        with open(transforms_path, "r") as f:
            self.meta = json.load(f)

        # Camera information
        self.camera_angle_x = self.meta["camera_angle_x"]

        self.images = []
        self.poses = []

        # Load images and poses
        self._load_data()

    def _load_data(self):

        all_images = []
        all_poses = []

        for frame in self.meta["frames"]:

            # -------------------------
            # IMAGE PATH
            # -------------------------

            file_path = frame["file_path"]

            # Remove "./" from the beginning
            file_path = file_path.lstrip("./")

            image_path = self.root_dir / file_path

            # Add image extension if missing
            if image_path.suffix == "":

                for ext in [".png", ".jpg", ".jpeg"]:

                    candidate = image_path.with_suffix(ext)

                    if candidate.exists():
                        image_path = candidate
                        break

            if not image_path.exists():
                raise FileNotFoundError(
                    f"Image not found: {image_path}"
                )

            # -------------------------
            # LOAD IMAGE
            # -------------------------

            image = Image.open(image_path).convert("RGBA")

            # Resize
            image = image.resize(
                (self.W, self.H),
                Image.Resampling.LANCZOS,
            )

            # Convert to NumPy
            image = np.array(image).astype(np.float32) / 255.0

            # Separate RGB and alpha
            rgb = image[..., :3]
            alpha = image[..., 3:4]

            # Composite on white background
            if self.white_background:

                rgb = rgb * alpha + (1.0 - alpha)

            else:

                rgb = rgb * alpha

            all_images.append(rgb)

            # -------------------------
            # CAMERA POSE
            # -------------------------

            pose = np.array(
                frame["transform_matrix"],
                dtype=np.float32,
            )

            all_poses.append(pose)

        # -------------------------
        # CONVERT TO TENSORS
        # -------------------------

        # Images: [N, H, W, 3]
        self.images = torch.from_numpy(
            np.stack(all_images)
        )

        # Poses: [N, 4, 4]
        self.poses = torch.from_numpy(
            np.stack(all_poses)
        )

    def __len__(self):

        return len(self.images)

    def __getitem__(self, idx):

        return {
            "image": self.images[idx],
            "pose": self.poses[idx],
        }


def create_dataloader(
    root_dir,
    split="train",
    img_wh=(400, 400),
    batch_size=1,
    shuffle=False,
    num_workers=0,
    white_background=True,
):

    dataset = BlenderNeRFDataset(
        root_dir=root_dir,
        split=split,
        img_wh=img_wh,
        white_background=white_background,
    )

    loader = DataLoader(
        dataset,
        batch_size=batch_size,
        shuffle=shuffle,
        num_workers=num_workers,
    )

    return dataset, loader
